                if (q !== expected_value) begin
                    $display("Error: Expected %b, got %b at time %0t", expected_value, q, $time);
                    errors = errors + 1;
                end
            end
        end

        // Final check for errors
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
